def _mock_time(variant_idx: int, round_idx: int) -> str:
    # 让同一case覆盖不同日期/时段，而不是固定周五下班
    start_times = [
        (8, 20),   # 早高峰出发
        (10, 45),  # 上午办事
        (13, 30),  # 午后出行
        (17, 40),  # 晚高峰
        (20, 10),  # 夜间返程
    ]
    hour, minute = start_times[variant_idx % len(start_times)]
    base = datetime(2026, 1, 5, hour, minute, 0) + timedelta(days=variant_idx * 3)
    dt = base + timedelta(days=round_idx * 5, minutes=(variant_idx * 4 + round_idx * 7) % 31)
    return dt.strftime("%Y-%m-%d %H:%M:%S")


def _car_info(mock_time: str, seed: int) -> str:
    weather = WEATHERS[seed % len(WEATHERS)]
    location = LOCATIONS[seed % len(LOCATIONS)]
    destinations = [
        "上海市浦东新区花园石桥路28弄汤臣一品",
        "上海市徐汇区宜山路900号漕河泾开发区",
        "上海市静安区南京西路1266号恒隆广场",
        "上海市闵行区申长路688号虹桥天地",
        "上海市杨浦区国顺东路800号复旦大学江湾校区",
        "上海市浦东新区锦绣路3891号世纪公园",
        "上海市黄浦区中山东一路3号外滩源",
        "上海市长宁区遵义路100号虹桥南丰城",
        "上海市普陀区真如副中心绿地缤纷城",
        "上海市浦东新区龙阳路2000号上海新国际博览中心",
    ]
    destination = destinations[(seed // 3) % len(destinations)]
    speed = 24 + (seed * 7) % 39
    temp_out = 9 + (seed * 3) % 25
    temp_in = 22 + (seed % 3)
    battery = 38 + (seed * 5) % 55
    range_km = 220 + (seed * 11) % 260
    hint = ARRIVAL_HINTS[seed % len(ARRIVAL_HINTS)]
    return f"""'当前系统时间': {mock_time},
'当前位置': '{location}',
'导航目的地': '{destination}',
'天气': '{weather}',
'车外温度': '{temp_out}摄氏度',
'车内温度': '{temp_in}摄氏度（自动舒适）',
'车辆当前档位': 'D档（前进档）',
'车辆当前行驶速度': '{speed} km/h（行驶中）',
'车辆动力模式（新能源车/混动车专用）': '纯电优先',
'动力电池电量百分比（新能源车必需）': '{battery}%',
'剩余续航里程（新能源车）': '{range_km} km',
'空调开启状态及模式': '自动模式',
'车内空气质量（智能车功能）': 'PM2.5 19μg/m³（优）',
'中控屏幕状态（智能车重点）': '导航回家 + {hint}',
'四轮胎压监测': '左前2.4bar，右前2.4bar，左后2.3bar，右后2.3bar（正常）',
'车辆告警/故障信息': '无告警'"""


def _round(query: str, mock_time: str, seed: int) -> DialogueRoundConfig:
    return DialogueRoundConfig(
        user_query_list=[Message(role="user", content=query)],
        mock_info={"car_info": _car_info(mock_time=mock_time, seed=seed)},
        mock_time=mock_time,
    )


